public class BraceMatchFinderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    public static void main(String[] args) {
        check("outer brace", 7, BraceMatchFinder.matchingBrace("a{b{c}d}e", 1));
        check("inner brace", 5, BraceMatchFinder.matchingBrace("a{b{c}d}e", 3));
        check("adjacent braces", 1, BraceMatchFinder.matchingBrace("{}", 0));
        check("index is not a brace", -1, BraceMatchFinder.matchingBrace("a{b}", 0));
        check("index out of range", -1, BraceMatchFinder.matchingBrace("a{b}", 99));
        check("never closed", -1, BraceMatchFinder.matchingBrace("class A { int x;", 8));
        check("balanced method body", true, BraceMatchFinder.isBalanced("class A { void f() { } }"));
        check("empty text is balanced", true, BraceMatchFinder.isBalanced(""));
        check("missing close is not balanced", false, BraceMatchFinder.isBalanced("class A {"));
        check("close before open is not balanced", false, BraceMatchFinder.isBalanced("}{"));
        finish();
    }
}

