public class BraceMatchFinder {

    public static int matchingBrace(String source, int openIndex) {
        if (openIndex < 0 || openIndex >= source.length()) {
            return -1;
        }
        if (source.charAt(openIndex) != '{') {
            return -1;
        }
        int depth = 0;
        for (int i = openIndex; i < source.length(); i++) {
            char c = source.charAt(i);
            if (c == '{') {
                depth++;
            } else if (c == '}') {
                depth--;
                if (depth == 0) {
                    return i;
                }
            }
        }
        return -1;
    }

    public static boolean isBalanced(String source) {
        int depth = 0;
        for (int i = 0; i < source.length(); i++) {
            char c = source.charAt(i);
            if (c == '{') {
                depth++;
            } else if (c == '}') {
                depth--;
                if (depth < 0) {
                    return false;
                }
            }
        }
        return depth == 0;
    }
}
